const message = $input.first().json.message;
const text = message.text || '';
const chatId = message.chat.id;
const userId = message.from.id;
const userName = message.from.first_name || 'User';

if (text.startsWith('/start')) {
  return { json: { command: 'start', chat_id: chatId, user_id: userId, user_name: userName } };
}

if (text.startsWith('/help')) {
  return { json: { command: 'help', chat_id: chatId } };
}

if (text.startsWith('/add')) {
  const parts = text.split(' ');
  const articleId = parts[1] || '';
  if (!articleId || !/^\d+$/.test(articleId)) {
    return { json: { command: 'error', chat_id: chatId, error_message: '❌ Неверный формат!\n\nИспользуйте: /add 123456789' } };
  }
  return { json: { command: 'add', chat_id: chatId, user_id: userId, user_name: userName, article_id: articleId } };
}

if (text.startsWith('/list')) {
  return { json: { command: 'list', chat_id: chatId, user_id: userId } };
}

if (text.startsWith('/remove')) {
  const parts = text.split(' ');
  const articleId = parts[1] || '';
  return { json: { command: 'remove', chat_id: chatId, user_id: userId, article_id: articleId } };
}

if (text.startsWith('/price')) {
  const parts = text.split(' ');
  const articleId = parts[1] || '';
  return { json: { command: 'price', chat_id: chatId, article_id: articleId } };
}

if (text.startsWith('/stats')) {
  return { json: { command: 'stats', chat_id: chatId, user_id: userId } };
}

return { json: { command: 'unknown', chat_id: chatId, text: text } };

const response = $input.first().json;
const articleId = $node['Parse Command'].json.article_id;
const chatId = $node['Parse Command'].json.chat_id;
const userId = $node['Parse Command'].json.user_id;
const userName = $node['Parse Command'].json.user_name;

if (!response || !response.data || !response.data.products || response.data.products.length === 0) {
  return {
    json: {
      error: true,
      chat_id: chatId,
      message: '❌ *Товар не найден!*\n\nПроверьте правильность артикула.\n\nПример: /add 123456789'
    }
  };
}

const product = response.data.products[0];

let price = 0;
if (product.salePriceU) {
  price = product.salePriceU / 100;
} else if (product.priceU) {
  price = product.priceU / 100;
}

const oldPrice = product.extended && product.extended.basicPriceU ? product.extended.basicPriceU / 100 : price;
const discount = oldPrice > price ? Math.round(((oldPrice - price) / oldPrice) * 100) : 0;

return {
  json: {
    article_id: articleId,
    chat_id: chatId,
    user_id: userId,
    user_name: userName,
    product_name: product.name || 'Без названия',
    brand: product.brand || 'Неизвестно',
    price: price,
    old_price: oldPrice,
    discount: discount,
    rating: product.rating || 0,
    feedbacks: product.feedbacks || 0,
    seller: product.supplier || 'Неизвестно',
    url: `https://www.wildberries.ru/catalog/${articleId}/detail.aspx`,
    timestamp: new Date().toISOString(),
    error: false
  }
};

const data = $input.first().json;
const chatId = data.chat_id;

const priceFormatted = data.price.toLocaleString('ru-RU');
const oldPriceFormatted = data.old_price.toLocaleString('ru-RU');

const discountText = data.discount > 0 ? `\n🔥 Скидка: ${data.discount}% (было ${oldPriceFormatted} ₽)` : '';

const message = `✅ *Добавлен на мониторинг!*\n\n📦 *${data.product_name}*\n🏷️ Бренд: ${data.brand}\n💰 Цена: ${priceFormatted} ₽${discountText}\n⭐ Рейтинг: ${data.rating}/5\n💬 Отзывов: ${data.feedbacks}\n🏪 Продавец: ${data.seller}\n🔗 [Открыть на WB](${data.url})\n\n🔔 Вы получите уведомление при изменении цены!\n\n💡 *Команды:*\n/list - Мои товары\n/price ${data.article_id} - Проверить цену`;

return {
  json: {
    chat_id: chatId,
    message: message
  }
};

return {
  json: {
    chat_id: $input.first().json.chat_id,
    message: $input.first().json.error_message || '❌ Неизвестная ошибка'
  }
};
